use crate::Project;
use serde::{Serialize,Deserialize};
use std::collections::{HashMap,HashSet};
use uuid::Uuid;
#[derive(Clone,Copy,Debug,Default,PartialEq,Eq,Serialize,Deserialize)]
pub enum Body { #[default] None, Static, Dynamic, Trigger }
#[derive(Clone,Debug,PartialEq,Serialize,Deserialize)]
pub struct Animation { pub columns:u32,pub rows:u32,pub frames:u32,pub fps:f32,pub looping:bool, #[serde(default)] pub start:u32 }
impl Default for Animation {fn default()->Self{Self{columns:1,rows:1,frames:1,fps:8.,looping:true,start:0}}}
impl Animation {pub fn frame(&self,t:f32)->u32{let total=self.columns.max(1).saturating_mul(self.rows.max(1));let start=self.start.min(total-1);let n=self.frames.max(1).min(total-start);let f=(t*self.fps.max(0.)) as u32;start+if self.looping{f%n}else{f.min(n-1)}} pub fn uv(&self,t:f32)->[[f32;2];4]{let c=self.columns.max(1);let r=self.rows.max(1);let f=self.frame(t);let x=(f%c) as f32/c as f32;let y=(f/c) as f32/r as f32;let w=1./c as f32;let h=1./r as f32;[[x,y],[x+w,y],[x+w,y+h],[x,y+h]]}}
#[derive(Clone,Copy,Debug,PartialEq,Eq,Serialize,Deserialize)]
pub enum NodeKind { Update, Trigger, MoveRight, MoveUp, Jump }
#[derive(Clone,Debug,Default,PartialEq,Serialize,Deserialize)]
pub struct Graph {pub nodes:Vec<NodeKind>,pub edges:Vec<[usize;2]>}
impl Graph {pub fn actions(&self,event:NodeKind)->Vec<NodeKind>{let mut queue:Vec<usize>=self.nodes.iter().enumerate().filter_map(|(i,n)|(*n==event).then_some(i)).collect();let mut seen=HashSet::new();let mut out=vec![];while let Some(i)=queue.pop(){if !seen.insert(i){continue}if let Some(n)=self.nodes.get(i){out.push(*n);for e in &self.edges{if e[0]==i{queue.push(e[1]);}}}}out}}
#[derive(Default)]
pub struct Simulation {pub elapsed:f32, velocity:HashMap<Uuid,f32>, touching:HashSet<(Uuid,Uuid)>, lua:HashMap<Uuid,(String,mlua::Lua)>, pub errors:Vec<String>}
fn overlap(a:&crate::Object,b:&crate::Object)->bool{(0..2).all(|i|(a.position[i]-b.position[i]).abs()<(a.size[i]+b.size[i])*0.5)}
impl Simulation {
 pub fn step(&mut self,p:&mut Project,dt:f32,input:[f32;2]){let dt=dt.clamp(0.,0.033);self.elapsed+=dt;let solids=p.objects.iter().filter(|o|o.body==Body::Static).cloned().collect::<Vec<_>>();let triggers=p.objects.iter().filter(|o|o.body==Body::Trigger).cloned().collect::<Vec<_>>();let mut contacts=HashSet::new();for o in &mut p.objects{if o.camera||matches!(o.body,Body::Static|Body::Trigger){continue}let old=o.position;if o.motion.auto_state && o.player {let name=if input[1]>0. {"Jump"}else if input[0].abs()>0.01 || input[1].abs()>0.01 {"Run"}else{"Idle"};if o.clip_name!=name {if let Some(clip)=o.clips.get(name){o.animation=clip.clone();o.clip_name=name.into();}}}if o.body==Body::None && !o.player {if let Some((pos,rot))=o.motion.sample(self.elapsed){o.position=pos;o.rotation=rot;}}let v=self.velocity.entry(o.id).or_default();if o.player {o.position[0]+=input[0]*200.*dt;if o.body!=Body::Dynamic{o.position[1]+=input[1]*200.*dt;}else if input[1]>0. && v.abs()<0.01{*v=320.;}}for n in o.graph.actions(NodeKind::Update){match n{NodeKind::MoveRight=>o.position[0]+=100.*dt,NodeKind::MoveUp=>o.position[1]+=100.*dt,NodeKind::Jump=>if v.abs()<0.01{*v=320.},_=>{}}}
 if !o.script.trim().is_empty(){let entry=self.lua.entry(o.id).or_insert_with(||(String::new(),mlua::Lua::new()));if entry.0!=o.script{entry.0=o.script.clone();entry.1=mlua::Lua::new();let lua=&entry.1;let _=lua.set_hook(mlua::HookTriggers::new().every_nth_instruction(10000),|_,_| Err(mlua::Error::RuntimeError("Instruction budget exceeded".into())));if let Err(e)=lua.load(&o.script).exec(){self.errors.push(e.to_string());}}let lua=&entry.1;let g=lua.globals();let _=g.set("x",o.position[0]);let _=g.set("y",o.position[1]);let _=g.set("input_x",input[0]);let _=g.set("input_y",input[1]);if let Ok(f)=g.get::<mlua::Function>("update"){match f.call::<()>(dt){Ok(())=>{if let (Ok(x),Ok(y))=(g.get::<f32>("x"),g.get::<f32>("y")){if x.is_finite()&&y.is_finite(){o.position=[x,y];}}},Err(e)=>self.errors.push(e.to_string())}}}
 if o.body==Body::Dynamic{let target_y=o.position[1];o.position[1]=old[1];for b in &solids{if overlap(o,b){o.position[0]=old[0];}}*v-=720.*dt;o.position[1]=target_y+*v*dt;for b in &solids{if overlap(o,b){let half=(o.size[1]+b.size[1])*0.5;o.position[1]=b.position[1]+if *v<=0.{half}else{-half};*v=0.;}}}for b in &triggers{if overlap(o,b){let pair=(o.id,b.id);contacts.insert(pair);if !self.touching.contains(&pair){for n in o.graph.actions(NodeKind::Trigger){match n{NodeKind::MoveRight=>o.position[0]+=32.,NodeKind::MoveUp=>o.position[1]+=32.,NodeKind::Jump=>*v=320.,_=>{}}}if let Some((_,lua))=self.lua.get(&o.id){if let Ok(f)=lua.globals().get::<mlua::Function>("on_trigger"){if let Err(e)=f.call::<()>(b.name.clone()){self.errors.push(e.to_string());}}}}}}}self.touching=contacts;if self.errors.len()>100{self.errors.drain(..self.errors.len()-100);}}
}
pub fn project_point(p:[f32;2],iso:bool)->[f32;2]{if iso{[(p[0]-p[1])*0.866,(p[0]+p[1])*0.5]}else{p}}
pub fn unproject_point(p:[f32;2],iso:bool)->[f32;2]{if iso{[p[1]+p[0]/1.732,p[1]-p[0]/1.732]}else{p}}
#[cfg(test)] mod tests{use super::*;#[test]fn atlas(){let a=Animation{columns:4,rows:2,frames:8,fps:4.,looping:true,start:0};assert_eq!(a.frame(2.),0);assert_eq!(a.frame(1.25),5);}#[test]fn graph_cycle(){let g=Graph{nodes:vec![NodeKind::Update,NodeKind::MoveRight],edges:vec![[0,1],[1,0]]};assert_eq!(g.actions(NodeKind::Update).len(),2);}#[test]fn projection(){let p=unproject_point(project_point([32.,64.],true),true);assert!((p[0]-32.).abs()<0.001);}}
